package domain;

import config.Settings;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/** Password rules shared by sign-up, password change and admin reset. */
public final class PasswordPolicy {
    private static final Settings SETTINGS = Settings.load();
    private static final int MIN_LENGTH = SETTINGS.intValue("password.minLength", 10);
    private static final boolean REQUIRE_DIGIT = SETTINGS.boolValue("password.requireDigit", true);

    /** The policy every account flow uses, built from application settings. */
    public static final PasswordPolicy DEFAULT = new PasswordPolicy();

    // password history
    private static final int REUSE_WINDOW = SETTINGS.intValue("password.reuseWindow", 5);

    private final int minLength;
    private final boolean requireDigit;
    private final int reuseWindow;

    private PasswordPolicy() {
        this(MIN_LENGTH, REQUIRE_DIGIT, REUSE_WINDOW);
    }

    public PasswordPolicy(int minLength, boolean requireDigit, int reuseWindow) {
        this.minLength = minLength;
        this.requireDigit = requireDigit;
        this.reuseWindow = reuseWindow;
    }

    public int minLength() {
        return minLength;
    }

    /** How many of the most recent passwords (current one included) may not be chosen again. */
    public int reuseWindow() {
        return reuseWindow;
    }

    /** Checks the shape of a candidate password. History is checked separately. */
    public List<PolicyViolation> check(String username, String candidate) {
        List<PolicyViolation> violations = new ArrayList<>();
        if (candidate == null || candidate.length() < minLength) {
            violations.add(PolicyViolation.TOO_SHORT);
            return violations;
        }
        if (requireDigit && candidate.chars().noneMatch(Character::isDigit)) {
            violations.add(PolicyViolation.MISSING_DIGIT);
        }
        if (username != null && !username.isBlank()
                && candidate.toLowerCase(Locale.ROOT).contains(username.toLowerCase(Locale.ROOT))) {
            violations.add(PolicyViolation.CONTAINS_USERNAME);
        }
        return violations;
    }
}
package domain;

public enum PolicyViolation {
    TOO_SHORT("password is too short"),
    MISSING_DIGIT("password must contain a digit"),
    CONTAINS_USERNAME("password must not contain the username"),
    RECENTLY_USED("password was used recently");

    private final String message;

    PolicyViolation(String message) {
        this.message = message;
    }

    public String message() {
        return message;
    }
}
package crypto;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;

/** Salted SHA-256, stored as {@code salt$digest} (both base64). */
public final class PasswordHasher {
    private static final int SALT_BYTES = 16;
    private static final int ROUNDS = 1_000;

    private final SecureRandom random = new SecureRandom();

    public String hash(String raw) {
        byte[] salt = new byte[SALT_BYTES];
        random.nextBytes(salt);
        return encode(salt) + "$" + encode(digest(salt, raw));
    }

    public boolean matches(String raw, String stored) {
        if (raw == null || stored == null) {
            return false;
        }
        int sep = stored.indexOf('$');
        if (sep <= 0) {
            return false;
        }
        byte[] salt = Base64.getDecoder().decode(stored.substring(0, sep));
        byte[] expected = Base64.getDecoder().decode(stored.substring(sep + 1));
        return MessageDigest.isEqual(expected, digest(salt, raw));
    }

    private static byte[] digest(byte[] salt, String raw) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] out = raw.getBytes(StandardCharsets.UTF_8);
            for (int i = 0; i < ROUNDS; i++) {
                md.reset();
                md.update(salt);
                md.update(out);
                out = md.digest();
            }
            return out;
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private static String encode(byte[] bytes) {
        return Base64.getEncoder().withoutPadding().encodeToString(bytes);
    }
}
package app;

import api.AccountHandler;
import api.AdminHandler;
import api.Request;
import api.Response;
import api.Router;
import api.SessionHandler;
import config.Settings;
import crypto.PasswordHasher;
import domain.PasswordPolicy;
import service.AccountService;
import service.LoginService;
import service.PasswordHistoryGuard;
import service.PasswordService;
import store.AccountStore;
import store.CredentialHistoryStore;
import store.SessionStore;

import java.time.Clock;
import java.time.Duration;

/** Wires the account service together. One instance = one running server. */
public final class Application {
    private final Router router;

    private Application(Router router) {
        this.router = router;
    }

    public static Application create(Clock clock, String adminKey) {
        Settings settings = Settings.load();
        AccountStore accounts = new AccountStore();
        SessionStore sessions = new SessionStore();
        PasswordHasher hasher = new PasswordHasher();
        PasswordHistoryGuard history = new PasswordHistoryGuard(new CredentialHistoryStore(), hasher);
        PasswordPolicy policy = PasswordPolicy.DEFAULT;
        Duration ttl = Duration.ofMinutes(settings.intValue("session.ttlMinutes", 30));

        AccountService accountService = new AccountService(accounts, hasher, history, policy, clock, settings);
        PasswordService passwordService = new PasswordService(accounts, sessions, hasher, history, policy, clock);
        LoginService loginService = new LoginService(accounts, sessions, hasher, clock, ttl);

        Router router = new Router(
                new AccountHandler(accountService, passwordService, loginService),
                new SessionHandler(loginService),
                new AdminHandler(adminKey, passwordService, accountService));
        return new Application(router);
    }

    public Response handle(Request request) {
        return router.handle(request);
    }
}

